import{_ as d,C as r,o as t,c as o,a2 as n,b as c,w as i,a as s,E as l,a3 as p}from"./chunks/framework.DZUUNQ77.js";const v=JSON.parse('{"title":"StubPending · PendingIntent 存根族","description":"","frontmatter":{},"headers":[],"relativePath":"reference/client/stub-pending.md","filePath":"reference/client/stub-pending.md","lastUpdated":1784053534000}'),u={name:"reference/client/stub-pending.md"};function g(E,e,A,b,P,S){const a=r("Mermaid");return t(),o("div",null,[e[1]||(e[1]=n('<h1 id="stubpending-·-pendingintent-存根族" tabindex="-1">StubPending · PendingIntent 存根族 <a class="header-anchor" href="#stubpending-·-pendingintent-存根族" aria-label="Permalink to &quot;StubPending · PendingIntent 存根族&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">源码路径</p><p><code>StubPendingActivity.java</code> · <code>StubPendingService.java</code> · <code>StubPendingReceiver.java</code>（<a href="https://github.com/android-security-engineer/VirtualXposed-skills/tree/vxp/VirtualApp/lib/src/main/java/com/lody/virtual/client/stub" target="_blank" rel="noreferrer">目录</a>）</p></div><p><code>StubPendingActivity</code> / <code>StubPendingService</code> / <code>StubPendingReceiver</code> 三个存根，让虚拟 App 注册的 PendingIntent 在真实系统触发后，能安全路由回虚拟环境。PendingIntent 跨进程、跨时间，身份一致性最难维护，这三个存根是关键。</p><h2 id="为什么-pendingintent-特殊" tabindex="-1">为什么 PendingIntent 特殊 <a class="header-anchor" href="#为什么-pendingintent-特殊" aria-label="Permalink to &quot;为什么 PendingIntent 特殊&quot;">​</a></h2><p>PendingIntent 是「预先创建、稍后由别人触发」的 Intent 句柄。虚拟 App 调 <code>PendingIntent.getActivity</code> 时，真实系统会按调用方身份校验。如果直接用虚拟 App 的真实 Intent 注册，触发时身份对不上。解法：</p><ol><li>注册时把真实 Intent 信息存到 server（<a href="./../remote/pendingintent-data"><code>PendingIntentData</code></a>）。</li><li>注册给真实系统的是指向 <code>StubPendingActivity</code> 的 Stub Intent。</li><li>触发时真实系统启动 <code>StubPending*</code>。</li><li>存根 <code>onCreate</code>/<code>onStartCommand</code>/<code>onReceive</code> 从 server 取回真实 Intent，转发给虚拟 App 的目标组件。</li></ol><h2 id="三件套" tabindex="-1">三件套 <a class="header-anchor" href="#三件套" aria-label="Permalink to &quot;三件套&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类</th><th>触发形态</th><th>还原方法</th></tr></thead><tbody><tr><td><code>StubPendingActivity extends Activity</code></td><td>Activity 启动</td><td><code>onCreate</code> 取真实 Intent 还原</td></tr><tr><td><code>StubPendingService extends Service</code></td><td>Service 启动</td><td><code>onStartCommand</code> 还原</td></tr><tr><td><code>StubPendingReceiver extends BroadcastReceiver</code></td><td>广播投递</td><td><code>onReceive</code> 还原</td></tr></tbody></table><h2 id="与真实组件的关系" tabindex="-1">与真实组件的关系 <a class="header-anchor" href="#与真实组件的关系" aria-label="Permalink to &quot;与真实组件的关系&quot;">​</a></h2><p>存根本身不做事，只把「真实系统认可的宿主身份」借给虚拟 PendingIntent 用，触发后立刻把控制权交还虚拟 App。</p><h2 id="pendingintent-注册与触发还原" tabindex="-1">PendingIntent 注册与触发还原 <a class="header-anchor" href="#pendingintent-注册与触发还原" aria-label="Permalink to &quot;PendingIntent 注册与触发还原&quot;">​</a></h2>',11)),(t(),c(p,null,{default:i(()=>[l(a,{id:"mermaid-101",class:"mermaid",graph:"sequenceDiagram%0A%20%20participant%20App%20as%20%E8%99%9A%E6%8B%9F%20App%0A%20%20participant%20SRV%20as%20server%0A%20%20participant%20Sys%20as%20%E7%9C%9F%E5%AE%9E%E7%B3%BB%E7%BB%9F%0A%20%20participant%20Stub%20as%20StubPending*%0A%20%20App-%3E%3ESys%3A%20PendingIntent.getActivity(%E7%9C%9F%E5%AE%9E%20Intent)%0A%20%20Note%20over%20App%2CSys%3A%20%E7%9C%9F%E5%AE%9E%20Intent%20%E5%AD%98%20server%2C%20%E6%B3%A8%E5%86%8C%20Stub%20Intent%20%E7%BB%99%E7%B3%BB%E7%BB%9F%0A%20%20Sys-%3E%3EStub%3A%20%E7%A8%8D%E5%90%8E%E8%A7%A6%E5%8F%91%20StubPending*%0A%20%20Stub-%3E%3ESRV%3A%20%E5%8F%96%E5%9B%9E%E7%9C%9F%E5%AE%9E%20Intent%0A%20%20SRV--%3E%3EStub%3A%20PendingIntentData%0A%20%20Stub-%3E%3EApp%3A%20%E8%BD%AC%E5%8F%91%E7%BB%99%E8%99%9A%E6%8B%9F%E7%9B%AE%E6%A0%87%E7%BB%84%E4%BB%B6%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=n('<h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="./../remote/pendingintent-data"><code>PendingIntentData</code> / <code>PendingResultData</code></a>：跨进程数据载体。</li><li><a href="./../server/am-classes/pending-intents"><code>PendingIntents</code></a>：server 端管理器。</li><li><a href="./../../features/stub-activity">Stub Activity 机制</a>。</li></ul>',2))])}const m=d(u,[["render",g]]);export{v as __pageData,m as default};
